#!/usr/bin/env python3
"""统计 CSV 文件中每一列的非空值数量。"""

import argparse
import csv
import sys
from collections import OrderedDict


def count_non_empty(path):
    counts = OrderedDict()
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            return counts, 0
        counts.update((name, 0) for name in header)
        rows = 0
        for row in reader:
            rows += 1
            for i, value in enumerate(row):
                if i < len(header) and value.strip():
                    counts[header[i]] += 1
    return counts, rows


def main(argv=None):
    parser = argparse.ArgumentParser(description="统计 CSV 每一列的非空值数量")
    parser.add_argument("csv_file", help="CSV 文件路径，用 - 表示标准输入")
    args = parser.parse_args(argv)

    if args.csv_file == "-":
        stream, path = sys.stdin, sys.stdin
    else:
        stream = open(args.csv_file, newline="", encoding="utf-8-sig")
        path = args.csv_file

    try:
        with stream:
            counts, rows = count_non_empty(path) if path is not sys.stdin else _from_stream(stream)
    except OSError as exc:
        print(f"错误: {exc}", file=sys.stderr)
        return 1

    if not counts:
        print("CSV 文件为空或没有表头。", file=sys.stderr)
        return 1

    width = max(len(name) for name in counts)
    for name, count in counts.items():
        print(f"{name.ljust(width)}  {count}")
    print(f"\n共 {rows} 行数据")
    return 0


def _from_stream(stream):
    counts = OrderedDict()
    reader = csv.reader(stream)
    header = next(reader, None)
    if header is None:
        return counts, 0
    counts.update((name, 0) for name in header)
    rows = 0
    for row in reader:
        rows += 1
        for i, value in enumerate(row):
            if i < len(header) and value.strip():
                counts[header[i]] += 1
    return counts, rows


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""统计 CSV 文件中每一列的非空值数量。"""

import argparse
import csv
import sys
from collections import OrderedDict


def count_non_empty(stream):
    """返回 (列名 -> 非空值数量, 数据行数)。非空指去除首尾空白后仍有内容。"""
    reader = csv.reader(stream)
    header = next(reader, None)
    if header is None:
        return OrderedDict(), 0

    counts = OrderedDict((name, 0) for name in header)
    rows = 0
    for row in reader:
        rows += 1
        for index, value in enumerate(row):
            if index < len(counts) and value.strip():
                counts[header[index]] += 1
    return counts, rows


def main(argv=None):
    parser = argparse.ArgumentParser(description="统计 CSV 每一列的非空值数量")
    parser.add_argument("csv_file", help="CSV 文件路径，用 - 表示标准输入")
    args = parser.parse_args(argv)

    if args.csv_file == "-":
        counts, rows = count_non_empty(sys.stdin)
    else:
        try:
            with open(args.csv_file, newline="", encoding="utf-8-sig") as f:
                counts, rows = count_non_empty(f)
        except OSError as exc:
            print(f"错误: {exc}", file=sys.stderr)
            return 1

    if not counts:
        print("错误: CSV 为空或缺少表头。", file=sys.stderr)
        return 1

    width = max(len(name) for name in counts)
    for name, count in counts.items():
        print(f"{name.ljust(width)}  {count}")
    print(f"\n共 {rows} 行数据")
    return 0


if __name__ == "__main__":
    sys.exit(main())
